            // when caller == owner (this contract), the reference allows the call only if receiver!=0 and amount>0
            // we ensure receiver == owner here and non-zero; so success iff amount>0
            if (amount > 0) {
                assertTrue(ok);
            } else {
                assertTrue(!ok);
            }
        }
    }
}

