        // admissible domain: receiver must be non-zero and amount > 0 and contract must have balance
        vm.assume(caller != address(0));
        vm.assume(amount > 0 && amount <= 1 ether);

        // fund the contract so payable transfer can succeed if call allowed
        vm.deal(address(c), 1 ether);

